// Settings are the adjustable parameters. Defaults returns the values
// calibrated against the own history.
type Settings struct {
	WindowDays int `json:"window_days"`
	// Weights of the readiness factors.
	WeightHRV   float64 `json:"weight_hrv"`
	WeightRHR   float64 `json:"weight_rhr"`
	WeightSleep float64 `json:"weight_sleep"`
	WeightBody  float64 `json:"weight_body"`
	WeightLoad  float64 `json:"weight_load"`
	// ReadyAt and LimitedBelow are the readiness class bounds.
	ReadyAt      float64 `json:"ready_at"`
	LimitedBelow float64 `json:"limited_below"`
	// Warning: resting HR at least WarnRHR bpm above its median on
	// WarnDays days in a row.
	WarnRHR  float64 `json:"warn_rhr"`
	WarnDays int     `json:"warn_days"`
	// Recommendation bounds for form (TSB) and the acute:chronic ratio.
	FormRest  float64 `json:"form_rest"`
	FormEasy  float64 `json:"form_easy"`
	FormHard  float64 `json:"form_hard"`
	RatioEasy float64 `json:"ratio_easy"`
	RatioRest float64 `json:"ratio_rest"`
}

// Defaults are the calibrated settings (docs/konzept-einordnung.md §12).
func Defaults() Settings {
	return Settings{WindowDays: 60, WeightHRV: 0.30, WeightRHR: 0.25, WeightSleep: 0.25, WeightBody: 0.20, WeightLoad: 0.30,
		ReadyAt: 66, LimitedBelow: 46, WarnRHR: 5, WarnDays: 3,
		FormRest: -20, FormEasy: -30, FormHard: -10, RatioEasy: 1.3, RatioRest: 1.5}
}

// Valid reports whether the settings are usable; invalid settings fall
// back to the defaults.
func (s Settings) Valid() bool {
	weights := []float64{s.WeightHRV, s.WeightRHR, s.WeightSleep, s.WeightBody, s.WeightLoad}
	for _, w := range weights {
		if w < 0 || w > 1 {
			return false
		}
	}
	return s.WindowDays >= 14 && s.WindowDays <= 365 && s.ReadyAt > s.LimitedBelow && s.LimitedBelow >= 0 &&
		s.ReadyAt <= 100 && s.WarnRHR > 0 && s.WarnDays >= 1 && s.WarnDays <= 14 &&
		s.RatioRest >= s.RatioEasy && s.RatioEasy > 0 && s.FormEasy <= s.FormRest && s.FormRest <= s.FormHard
}

// minDays is the minimum number of values for a normal range.
const minDays = 14

// Readiness classes.
const (
	ClassReady   = "bereit"
	ClassNormal  = "normal"
	ClassLimited = "eingeschränkt"
)

// Factor is one input of the readiness with its points (0–100).
type Factor struct {
	Key    string
	Label  string
	Text   string
	Z      float64
	Points float64
	Weight float64
}

// Readiness is the readiness of a day.
type Readiness struct {
	Day     time.Time
	Score   float64
	Class   string
	Factors []Factor
	// Reasons are the decisive factors: the weakest for normal/limited, the
	// strongest for ready.
	Reasons []string
	Warning string
}

// points maps a favourable z to 0–100: 70 at the median, ±30 per spread.
func points(z float64) float64 { return math.Max(0, math.Min(100, 70+30*z)) }

// ComputeReadiness evaluates day. fitness must contain the day before (for
// the load factor); ok is false with fewer than two recovery factors.
func ComputeReadiness(s Series, fitness map[time.Time]analysis.FitnessDay, day time.Time, cfg Settings) (Readiness, bool) {
	r := Readiness{Day: day}
	add := func(f Factor) { r.Factors = append(r.Factors, f) }

	// HRV: Garmin's own baseline takes precedence.
	if v, ok := s.Value(HRV, day); ok {
		lo, okLo := s.Value(HRVLow, day)
		hi, okHi := s.Value(HRVHigh, day)
		switch {
		case okLo && okHi && hi > lo:
			z := 0.0
			if v < lo {
				z = (v - lo) / math.Max((hi-lo)/2, 2)
			}
			text := fmt.Sprintf("HRV %.0f ms im Basisbereich (%.0f–%.0f)", v, lo, hi)
			if v < lo {
				text = fmt.Sprintf("HRV %.0f ms unter deiner Basis (%.0f–%.0f)", v, lo, hi)
			}
			add(Factor{Key: HRV, Label: "HRV", Text: text, Z: z})
		default:
			if d, ok := DeviationOn(s, HRV, day, cfg.WindowDays, minDays); ok {
				add(Factor{Key: HRV, Label: "HRV", Text: describe(d), Z: d.Z})
			}
		}
	}
	if d, ok := DeviationOn(s, RestingHR, day, cfg.WindowDays, minDays); ok {
		add(Factor{Key: RestingHR, Label: "Ruhepuls", Text: describe(d), Z: d.Z})
	}
	if f, ok := worse(s, day, cfg, Sleep, SleepScr); ok {
		f.Key, f.Label = Sleep, "Schlaf"
		add(f)
	}
	// Body Battery and stress are daily totals: in the morning today's values
	// cover only a few hours, so the last complete day (yesterday) counts.
	if f, ok := worse(s, day.AddDate(0, 0, -1), cfg, BodyHigh, Stress); ok {
		f.Key, f.Label, f.Text = BodyHigh, "Body Battery/Stress", f.Text+" (gestern)"
		add(f)
	}
	if len(r.Factors) < 2 {
		return r, false
	}
	if y, ok := fitness[day.AddDate(0, 0, -1)]; ok && y.ACWR > 0 {
		pct := (y.ACWR - 1) * 100
		text := fmt.Sprintf("Belastung der letzten 7 Tage im Rahmen deines Üblichen (%+.0f %%)", pct)
		if pct >= 15 {
			text = fmt.Sprintf("Belastung der letzten 7 Tage %.0f %% über deinem Üblichen", pct)
		} else if pct <= -15 {
			text = fmt.Sprintf("Belastung der letzten 7 Tage %.0f %% unter deinem Üblichen", -pct)
		}
		add(Factor{Key: "load", Label: "Belastung", Text: text, Z: -(y.ACWR - 1) / 0.3})
	}

	weight := map[string]float64{HRV: cfg.WeightHRV, RestingHR: cfg.WeightRHR, Sleep: cfg.WeightSleep, BodyHigh: cfg.WeightBody, "load": cfg.WeightLoad}
	var sum, total float64
	for i := range r.Factors {
		f := &r.Factors[i]
		f.Points, f.Weight = points(f.Z), weight[f.Key]
		sum += f.Points * f.Weight
		total += f.Weight
	}
	if total == 0 {
		return r, false
	}
	r.Score = math.Round(sum / total)
	switch {
	case r.Score >= cfg.ReadyAt:
		r.Class = ClassReady
	case r.Score < cfg.LimitedBelow:
		r.Class = ClassLimited
	default:
		r.Class = ClassNormal
	}
	sorted := append([]Factor(nil), r.Factors...)
	sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].Points < sorted[j].Points })
	if r.Class == ClassReady {
		sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].Points > sorted[j].Points })
	}
	for _, f := range sorted[:min(2, len(sorted))] {
		r.Reasons = append(r.Reasons, f.Text)
	}
	r.Warning = warning(s, day, cfg)
	return r, true
}

// worse returns the less favourable of two metrics as factor.
func worse(s Series, day time.Time, cfg Settings, a, b string) (Factor, bool) {
	var best *Deviation
	for _, m := range []string{a, b} {
		if d, ok := DeviationOn(s, m, day, cfg.WindowDays, minDays); ok && (best == nil || d.Z < best.Z) {
			dd := d
			best = &dd
		}
	}
	if best == nil {
		return Factor{}, false
	}
	return Factor{Text: describe(*best), Z: best.Z}, true
}

// warning checks the resting heart rate for WarnDays days in a row at
// least WarnRHR above its median; HRV below the baseline is added as
// reinforcing reason.
func warning(s Series, day time.Time, cfg Settings) string {
	for i := range cfg.WarnDays {
		d := day.AddDate(0, 0, -i)
		v, ok := s.Value(RestingHR, d)
		n, okN := NormalFor(s, RestingHR, d, cfg.WindowDays, minDays)
		if !ok || !okN || v-n.Median < cfg.WarnRHR {
			return ""
		}
	}
	text := fmt.Sprintf("Ruhepuls seit %d Tagen mindestens %.0f bpm über deinem Normal", cfg.WarnDays, cfg.WarnRHR)
	if v, ok := s.Value(HRV, day); ok {
		if lo, ok := s.Value(HRVLow, day); ok && v < lo {
			text += " und HRV unter deiner Basis"
		}
	}
	return text + ". Mögliche Überlastung oder beginnender Infekt – Belastung reduzieren, bei Beschwerden ärztlich abklären."
}

// describe formats a deviation, e.g. "Ruhepuls 57 bpm, dein Normal 50–53".
func describe(d Deviation) string {
	name := map[string]string{RestingHR: "Ruhepuls", HRV: "HRV", Sleep: "Schlaf", SleepScr: "Schlafwert",
		BodyHigh: "Body Battery max.", Stress: "Stress"}[d.Metric]
	lo, hi := d.Normal.Range(d.Metric)
	return fmt.Sprintf("%s %s, dein Normal %s", name, FormatValue(d.Metric, d.Value), FormatRange(d.Metric, lo, hi))
}

// FormatRange formats a range with the unit once, e.g. "49–51 bpm".
func FormatRange(metric string, lo, hi float64) string {
	l, h := FormatValue(metric, lo), FormatValue(metric, hi)
	if i := strings.LastIndex(h, " "); i > 0 && strings.HasSuffix(l, h[i:]) {
		return strings.TrimSuffix(l, h[i:]) + "–" + h
	}
	return l + "–" + h
}

// FormatValue formats a metric value with unit in German notation.
func FormatValue(metric string, v float64) string {
	switch metric {
	case RestingHR:
		return fmt.Sprintf("%.0f bpm", v)
	case HRV:
		return fmt.Sprintf("%.0f ms", v)
	case Sleep:
		m := int(math.Round(v / 60))
		return fmt.Sprintf("%d:%02d h", m/60, m%60)
	}
	return strings.Replace(fmt.Sprintf("%.0f", v), ".", ",", 1)
}

// Recommendation kinds.
const (
	RecRest     = "Ruhetag sinnvoll"
	RecEasy     = "Locker"
	RecModerate = "Moderat / nach Gefühl"
	RecHard     = "Intensiv möglich"
)

// Recommendation is the training advice of a day with its reasons and
// hints about the longer-term development.
type Recommendation struct {
	Kind    string
	Reasons []string
	Hints   []string
}

// Recommend combines readiness (nil without current health data), the
// fitness model and the recent daily loads. q75 is the 75th percentile of
// the daily load on training days.
func Recommend(r *Readiness, fitness map[time.Time]analysis.FitnessDay, loads map[time.Time]float64, day time.Time, q75 float64, cfg Settings) Recommendation {
	var rec Recommendation
	today, ok := fitness[day]
	yesterday := fitness[day.AddDate(0, 0, -1)]
	form := today.Form
	ratio := yesterday.ACWR
	if !ok {
		form, ratio = 0, 0
	}
	class := ClassNormal
	if r != nil {
		class = r.Class
	}
	hardDays := 0
	for i := 1; i <= 3; i++ {
		if q75 > 0 && loads[day.AddDate(0, 0, -i)] > q75 {
			hardDays++
		}
	}
	formText := fmt.Sprintf("Form %+.0f", form)
	ratioText := "Verhältnis akut/chronisch " + strings.Replace(fmt.Sprintf("%.2f", ratio), ".", ",", 1)
	switch {
	case r != nil && r.Warning != "":
		rec.Kind, rec.Reasons = RecRest, []string{"Warnzeichen beim Ruhepuls"}
	case class == ClassLimited && (form < cfg.FormRest || ratio > cfg.RatioRest):
		rec.Kind, rec.Reasons = RecRest, []string{"Bereitschaft eingeschränkt", formText, ratioText}
	case class == ClassLimited:
		rec.Kind, rec.Reasons = RecEasy, []string{"Bereitschaft eingeschränkt"}
	case form < cfg.FormEasy:
		rec.Kind, rec.Reasons = RecEasy, []string{formText + " – deutlich ermüdet"}
	case ratio > cfg.RatioEasy:
		rec.Kind, rec.Reasons = RecEasy, []string{ratioText + " – Belastung zuletzt hoch"}
	case hardDays == 3:
		rec.Kind, rec.Reasons = RecEasy, []string{"drei harte Tage in Folge"}
	case class == ClassReady && form >= cfg.FormHard && ratio <= cfg.RatioEasy:
		rec.Kind, rec.Reasons = RecHard, []string{"gut erholt", formText}
	default:
		rec.Kind, rec.Reasons = RecModerate, []string{formText, ratioText}
	}
	if r == nil {
		rec.Reasons = append(rec.Reasons, "ohne aktuelle Gesundheitsdaten – nur aus der Belastung")
	}

	// Development of fitness.
	if week, ok := fitness[day.AddDate(0, 0, -7)]; ok && today.Fitness-week.Fitness > 8 {
		rec.Hints = append(rec.Hints, fmt.Sprintf("Fitness steigt schnell (+%.0f in 7 Tagen) – auf Erholung achten.", today.Fitness-week.Fitness))
	}
	if month, ok := fitness[day.AddDate(0, 0, -28)]; ok && month.Fitness > 10 && today.Fitness < month.Fitness*0.9 {
		rec.Hints = append(rec.Hints, fmt.Sprintf("Fitness nimmt ab (%.0f → %.0f in 4 Wochen).", month.Fitness, today.Fitness))
	}
	low := true
	for i := range 14 {
		if d, ok := fitness[day.AddDate(0, 0, -i)]; !ok || d.ACWR == 0 || d.ACWR >= 0.8 {
			low = false
			break
		}
	}
	if low {
		rec.Hints = append(rec.Hints, "Belastung seit zwei Wochen deutlich unter deinem Niveau.")
	}
	return rec
}

// Quantile75 returns the 75th percentile of the positive daily loads.
func Quantile75(loads map[time.Time]float64) float64 {
	var xs []float64
	for _, v := range loads {
		if v > 0 {
			xs = append(xs, v)
		}
	}
	if len(xs) == 0 {
		return 0
	}
	sort.Float64s(xs)
	return xs[int(0.75*float64(len(xs)-1))]
}
